CREATE SCHEMA IF NOT EXISTS keycloak;
CREATE TABLE IF NOT EXISTS schema_migrations (version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE customers (id uuid PRIMARY KEY, name text NOT NULL, reference text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE identities (subject text PRIMARY KEY, display_name text NOT NULL, enabled boolean NOT NULL DEFAULT true);
CREATE TABLE applications (id text PRIMARY KEY, name text NOT NULL, description text NOT NULL DEFAULT '', catalog_version integer NOT NULL DEFAULT 0);
CREATE TABLE catalogs (app_id text REFERENCES applications(id), version integer NOT NULL CHECK(version > 0), document jsonb NOT NULL, PRIMARY KEY(app_id,version));
CREATE TABLE features (app_id text REFERENCES applications(id), key text, name text NOT NULL, active boolean NOT NULL DEFAULT true, PRIMARY KEY(app_id,key));
CREATE TABLE permissions (app_id text, key text, feature_key text NOT NULL, name text NOT NULL, active boolean NOT NULL DEFAULT true, PRIMARY KEY(app_id,key), FOREIGN KEY(app_id,feature_key) REFERENCES features(app_id,key));
CREATE TABLE installations (id uuid PRIMARY KEY, customer_id uuid NOT NULL REFERENCES customers(id), app_id text NOT NULL REFERENCES applications(id), domain text NOT NULL, description text NOT NULL DEFAULT '', integration text NOT NULL DEFAULT 'web' CHECK(integration IN ('web','wordpress')), base_path text NOT NULL DEFAULT '', fallback_url text NOT NULL, secret_hash text NOT NULL, enabled boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,customer_id,app_id));
CREATE TABLE licenses (customer_id uuid REFERENCES customers(id), app_id text REFERENCES applications(id), state text NOT NULL CHECK(state IN ('active','suspended','expired')), expires_at timestamptz, PRIMARY KEY(customer_id,app_id));
CREATE TABLE entitlements (customer_id uuid, app_id text, feature_key text, purchased boolean NOT NULL DEFAULT false, enabled boolean NOT NULL DEFAULT false, PRIMARY KEY(customer_id,app_id,feature_key), FOREIGN KEY(customer_id,app_id) REFERENCES licenses(customer_id,app_id), FOREIGN KEY(app_id,feature_key) REFERENCES features(app_id,key));
CREATE TABLE roles (id uuid PRIMARY KEY, customer_id uuid NOT NULL REFERENCES customers(id), app_id text NOT NULL REFERENCES applications(id), name text NOT NULL, UNIQUE(id,customer_id,app_id), UNIQUE(id,app_id));
CREATE TABLE role_permissions (role_id uuid REFERENCES roles(id) ON DELETE CASCADE, app_id text, permission_key text, PRIMARY KEY(role_id,permission_key), FOREIGN KEY(app_id,permission_key) REFERENCES permissions(app_id,key), FOREIGN KEY(role_id,app_id) REFERENCES roles(id,app_id));
CREATE TABLE memberships (subject text REFERENCES identities(subject), customer_id uuid REFERENCES customers(id), enabled boolean NOT NULL DEFAULT true, PRIMARY KEY(subject,customer_id));
CREATE TABLE assignments (subject text, customer_id uuid, app_id text, role_id uuid, PRIMARY KEY(subject,role_id), FOREIGN KEY(subject,customer_id) REFERENCES memberships(subject,customer_id), FOREIGN KEY(role_id,customer_id,app_id) REFERENCES roles(id,customer_id,app_id));
CREATE TABLE local_links (installation_id uuid REFERENCES installations(id), local_user_id text, subject text NOT NULL REFERENCES identities(subject), PRIMARY KEY(installation_id,local_user_id), UNIQUE(installation_id,subject));
CREATE TABLE pairing_codes (hash text PRIMARY KEY, installation_id uuid NOT NULL REFERENCES installations(id), expires_at timestamptz NOT NULL, consumed_at timestamptz);
CREATE TABLE technical_tickets (hash text PRIMARY KEY, installation_id uuid NOT NULL REFERENCES installations(id), subject text NOT NULL, authorization_cipher text NOT NULL, expires_at timestamptz NOT NULL, consumed_at timestamptz);
CREATE TABLE audit (id bigserial PRIMARY KEY, actor text NOT NULL, action text NOT NULL, target text NOT NULL, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE runners (id text PRIMARY KEY, capacity integer NOT NULL CHECK(capacity > 0), heartbeat_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE wa_archives (id uuid PRIMARY KEY, installation_id uuid NOT NULL REFERENCES installations(id), number text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(installation_id,number));
CREATE TABLE wa_sessions (id uuid PRIMARY KEY, installation_id uuid NOT NULL REFERENCES installations(id), runner_id text NOT NULL, archive_id uuid REFERENCES wa_archives(id), number text, state text NOT NULL CHECK(state IN ('queued','pairing','connected','disconnecting','disconnected','failed')), qr text, sync_status text NOT NULL DEFAULT 'not_started', sync_count integer NOT NULL DEFAULT 0, sync_limit text NOT NULL DEFAULT 'Solo storico disponibile da WhatsApp; completezza non garantita.', created_at timestamptz NOT NULL DEFAULT now(), closed_at timestamptz);
CREATE UNIQUE INDEX wa_one_number ON wa_sessions(number) WHERE closed_at IS NULL AND number IS NOT NULL;
CREATE UNIQUE INDEX wa_one_installation ON wa_sessions(installation_id) WHERE closed_at IS NULL;
CREATE TABLE messages (id uuid PRIMARY KEY, session_id uuid NOT NULL REFERENCES wa_sessions(id), archive_id uuid NOT NULL REFERENCES wa_archives(id), provider_id text NOT NULL, chat_id text NOT NULL, direction text NOT NULL, kind text NOT NULL, body jsonb NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now(), UNIQUE(archive_id,provider_id));
CREATE TABLE outbox (id uuid PRIMARY KEY, installation_id uuid NOT NULL REFERENCES installations(id), session_id uuid NOT NULL REFERENCES wa_sessions(id), idempotency_key text NOT NULL, request_hash text NOT NULL, payload jsonb NOT NULL, actor text NOT NULL, authorization_cipher text NOT NULL, state text NOT NULL DEFAULT 'queued' CHECK(state IN ('queued','sending','sent','failed','uncertain','cancelled')), provider_id text, error text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(installation_id,idempotency_key));
CREATE TABLE webhook_endpoints (id uuid PRIMARY KEY, installation_id uuid NOT NULL REFERENCES installations(id), url text NOT NULL, secret_cipher text NOT NULL, enabled boolean NOT NULL DEFAULT true);
CREATE TABLE events (id uuid PRIMARY KEY, installation_id uuid NOT NULL REFERENCES installations(id), session_id uuid NOT NULL REFERENCES wa_sessions(id), kind text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE deliveries (id uuid PRIMARY KEY, event_id uuid NOT NULL REFERENCES events(id), endpoint_id uuid NOT NULL REFERENCES webhook_endpoints(id), state text NOT NULL DEFAULT 'queued', attempts integer NOT NULL DEFAULT 0, last_status integer, next_attempt_at timestamptz NOT NULL DEFAULT now(), last_error text, UNIQUE(event_id,endpoint_id));

CREATE INDEX messages_archive_time ON messages(archive_id,occurred_at DESC,id DESC);
